import json, sys, glob
S = '/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/'
h = json.load(open(S + 'mc_hits.json'))
mode = sys.argv[1]
if mode == 'guide':
    for r in h:
        if r.get('area') == 'multicam' and r['id'].startswith('guide-'):
            print(json.dumps({k: v for k, v in r.items() if k not in ('_f', 'area')}, ensure_ascii=False))
elif mode == 'code':
    for r in h:
        if r.get('area') == 'multicam' and not r['id'].startswith('guide-'):
            print(json.dumps({k: v for k, v in r.items() if k not in ('_f', 'area')}, ensure_ascii=False))
elif mode == 'other':
    ids = "code-analysis-ai-001 code-analysis-ai-006 code-analysis-ai-010 code-analysis-ai-015 code-analysis-ai-021 code-analysis-ai-049 code-history-155 code-roadmaps-004 code-sheets-143 code-screens-494 code-screens-585 code-screens-586 guide-menus-and-shortcuts-380 guide-mcp-182 code-mcp-catalog-032 guide-mcp-039".split()
    for r in h:
        if r['id'] in ids:
            print(json.dumps({k: v for k, v in r.items() if k != '_f'}, ensure_ascii=False))
    t = json.load(open(S + 'inventory/taxonomy.json'))
    print('=== taxonomy')
    for s in t['sections']:
        for p in s['pages']:
            b = json.dumps(p, ensure_ascii=False)
            if 'ynchron' in b or 'nalyz' in b:
                print(s['id'], p['slug'], p['title'], '::', p['scope'][:200])
    print('=== features')
    for f in glob.glob(S + 'inventory/features/*.json'):
        d = json.load(open(f))
        for x in d['features']:
            if 'ynchroni' in x['name'] or 'Analyzing' in x['name']:
                print(f.split('/')[-1], x['id'], x['name'], x['page'])
        for x in d['rejected']:
            if 'multicam' in x['reason']:
                print(f.split('/')[-1], x)

