h = json.load(open(S + 'mc_hits.json'))
mode = sys.argv[1]
if mode == 'guide':
    for r in h:
        if r.get('area') == 'multicam' and r['id'].startswith('guide-'):
            print(json.dumps({k: v for k, v in r.items() if k not in ('_f', 'area')}, ensure_ascii=False))
elif mode == 'code':
