53	
54	    // MARK: - The labels (SW-81)
55	
56	    /// One label per step: `.person(angle track)`, `.crosstalk` or `.nobody`. A step is speech
57	    /// when the shared microphone covers it at v ≥ `voice_threshold`; the face speakers' angles
58	    /// contest it front first.
59	    static func faceLabels(_ input: Input) -> [Label] {
60	        let step = stepTicks
61	        let count = step > 0 ? Int(max(0, input.to - input.from) / step) : 0
62	        let nobody = [Label](repeating: .nobody, count: count)
63	        let speakers = faceSpeakers(input.pairing)
64	        guard let micTrack = speakers.first?.mic,
65	            let mic = input.microphones.first(where: { $0.track == micTrack }),
66	            mic.voice.count == count, mic.covered.count == count
67	        else { return nobody }
68	        let order = input.angles.map(\.track)
69	        let contest = speakers.compactMap(\.angle)
70	            .sorted { (order.firstIndex(of: $0) ?? .max) < (order.firstIndex(of: $1) ?? .max) }
71	        let series: [(UInt32, [Double?])] = contest.map { angle in
72	            let read = input.faces.first { $0.track == angle }?.activity ?? []
73	            return (angle, read.count == count ? read : [Double?](repeating: nil, count: count))
74	        }
75	        let threshold = input.settings.voiceThreshold
76	        return (0..<count).map { k in
77	            FaceActivity.label(
78	                speech: mic.covered[k] && mic.voice[k] >= threshold,
79	                activities: series.map { (angle: $0.0, activity: $0.1[k]) },
80	                ratio: input.settings.faceRatio, floor: input.settings.faceFloor)
81	        }
82	    }
83	
84	    /// An angle clip as the faces series reads it: its span, its times, its media's sample grid
85	    /// and duration, and the media's activity per grid index.
86	    struct FaceClip {
87	        let span: Span
88	        let times: AnalysisClipTimes
89	        let grid: AnalysisGrid
90	        let duration: Ticks
91	        let activity: [Double?]
92	    }
93	
94	    /// Step k's activity: the sample nearest the forward source tick of the step's midpoint,
95	    /// through the covering clip (the later-starting where two cover); nil off every clip or
96	    /// outside the media's 0…duration.
97	    static func faceSeries(_ clips: [FaceClip], from: Ticks, count: Int) -> [Double?] {
98	        let step = stepTicks
99	        return (0..<max(0, count)).map { k -> Double? in
100	            let mid = from + Ticks(k) * step + step / 2
101	            var covering: FaceClip?
102	            for clip in clips where clip.span.start <= mid && mid < clip.span.end {
103	                if covering.map({ clip.span.start >= $0.span.start }) ?? true { covering = clip }
104	            }
105	            guard let clip = covering else { return nil }
106	            let source = clip.times.source(atClip: mid - clip.span.start)
107	            guard source >= 0, source <= clip.duration else { return nil }
108	            let index = clip.grid.index(of: source)
109	            return index < clip.activity.count ? clip.activity[index] : nil
110	        }
111	    }
112	
113	    // MARK: - The store (SW-84)
114	
115	    /// A face speaker's angle clip of moving-video media crossing the range, and the window of
116	    /// its media the faces series needs: the part inside the range in source ticks, widened by
117	    /// half the activity window and clamped to 0…duration.
118	    struct FaceWindow {
119	        let track: UInt32
120	        let span: Span
121	        let media: MediaSnapshot
122	        let times: AnalysisClipTimes
123	        let window: ClosedRange<Ticks>
124	    }
125	
126	    static func faceWindows(
127	        in project: ReelProject, angles: [AngleTrack], pairing: Pairing, from: Ticks, to: Ticks
128	    ) -> [FaceWindow] {
129	        let snapshot = project.snapshot
130	        let wanted = Set(faceSpeakers(pairing).compactMap(\.angle))
131	        let half = Ticks((FaceActivity.window / 2 * Double(ReelTime.perSecond)).rounded())
132	        var out: [FaceWindow] = []
133	        for angle in angles where wanted.contains(angle.track) {
134	            for span in angle.clips where span.end > from && span.start < to {
135	                guard let clip = snapshot.clip(span.clip), let media = snapshot.media(for: clip),
136	                    media.kind == .video, media.hasVideo
137	                else { continue }
138	                let times = AnalysisClipTimes(clip: clip, media: media, map: project.sourceMap(clip.id))
139	                let a = times.source(atClip: max(span.start, from) - span.start)
140	                let b = times.source(atClip: min(span.end, to) - span.start)
141	                let low = max(0, min(a, b) - half)
142	                let high = min(media.duration, max(a, b) + half)
143	                guard high > low else { continue }
144	                out.append(FaceWindow(
145	                    track: angle.track, span: span, media: media, times: times, window: low...high))
146	            }
147	        }
148	        return out
149	    }
