151	    /// The media's activity per grid index from the cached samples: each index the marker covers
152	    /// has the opening of its sample, the rest none.
153	    static func storedActivity(_ media: MediaSnapshot, grid: AnalysisGrid, cacheDir: URL)
154	        -> [Double?]
155	    {
156	        var openings = [Double?](repeating: nil, count: grid.count)
157	        if let marker = AnalysisStore.readMarker(.faces, media: media.id, in: cacheDir),
158	            let file = marker.files.first,
159	            let data = AnalysisStore.readPayload(.faces, media: media.id, file: file, in: cacheDir),
160	            let decoded = AnalysisFaces.decode(data), decoded.count == grid.count
161	        {
162	            for range in marker.ranges {
163	                for k in max(0, range.lowerBound)...min(grid.lastIndex, range.upperBound) {
164	                    openings[k] = FaceActivity.opening(decoded.samples[k])
165	                }
166	            }
167	        }
168	        let rate = grid.rate * Double(ReelTime.perSecond)
169	        return FaceActivity.activities(openings, half: FaceActivity.halfWidth(rate: rate))
170	    }
171	
172	    /// Each face speaker's angle, front first, on the range's grid, and the "still being
173	    /// analysed" problem for an angle any of whose windows the store does not answer (read as
174	    /// `[]`). Main thread.
175	    static func readFaces(
176	        from document: ProjectDocument, angles: [AngleTrack], pairing: Pairing, from: Ticks,
177	        count: Int
178	    ) -> (faces: [FaceAngle], problems: [String]) {
179	        let to = from + Ticks(max(0, count)) * stepTicks
180	        let windows = faceWindows(
181	            in: document.editedProject, angles: angles, pairing: pairing, from: from, to: to)
182	        let wanted = Set(faceSpeakers(pairing).compactMap(\.angle))
183	        var activity: [UInt32: [Double?]] = [:]
184	        var faces: [FaceAngle] = []
185	        var problems: [String] = []
186	        for angle in angles where wanted.contains(angle.track) {
187	            var clips: [FaceClip] = []
188	            var pending = false
189	            for window in windows where window.track == angle.track {
190	                let missed: Bool
191	                do {
192	                    missed = try document.analysisRequest(
193	                        kind: .faces, media: window.media, window: window.window) != nil
194	                } catch {
195	                    missed = true
196	                }
197	                guard !missed, let cacheDir = document.cacheDirectory else {
198	                    pending = true
199	                    continue
200	                }
201	                let grid = AnalysisKind.faces.grid(of: window.media)
202	                let stored = activity[window.media.id]
203	                    ?? storedActivity(window.media, grid: grid, cacheDir: cacheDir)
204	                activity[window.media.id] = stored
205	                clips.append(FaceClip(
206	                    span: window.span, times: window.times, grid: grid,
207	                    duration: window.media.duration, activity: stored))
208	            }
209	            if pending {
210	                problems.append(
211	                    "The camera on track \(angle.track) is still being analysed — its faces have "
212	                        + "not been found yet. Try again in a moment.")
213	                faces.append(FaceAngle(track: angle.track, activity: []))
214	            } else {
215	                faces.append(FaceAngle(
216	                    track: angle.track, activity: faceSeries(clips, from: from, count: count)))
217	            }
218	        }
219	        return (faces, problems)
220	    }
221	
222	    /// One `faces` request a media still needs, and the first face-speaker angle clip needing it.
223	    struct FacesWant {
224	        let track: UInt32
225	        let clip: UInt32
226	        let media: MediaSnapshot
227	        let request: AnalysisRequest
228	    }
229	
230	    /// The requests the faces mode still needs, one per media in first-window order, each
231	    /// media's misses merged (`ShotSplit.wants`' shape); empty in the microphones mode or when
232	    /// every window is a hit. Main thread; throws `analysisRequest`'s errors.
233	    static func facesWanted(_ input: Input, in document: ProjectDocument) throws -> [FacesWant] {
234	        guard mode(input.pairing) == .faces else { return [] }
235	        let windows = faceWindows(
236	            in: document.editedProject, angles: input.angles, pairing: input.pairing,
237	            from: input.from, to: input.to)
238	        var order: [UInt32] = []
239	        var misses: [UInt32: [AnalysisRequest]] = [:]
240	        var first: [UInt32: FaceWindow] = [:]
241	        for window in windows {
242	            guard let request = try document.analysisRequest(
243	                kind: .faces, media: window.media, window: window.window)
244	            else { continue }
245	            let id = window.media.id
246	            if misses[id] == nil {
247	                order.append(id)
248	                first[id] = window
249	            }
250	            misses[id, default: []].append(request)
251	        }
252	        return order.compactMap { id in
253	            guard let requests = misses[id], let head = requests.first, let window = first[id]
254	            else { return nil }
255	            let request = AnalysisRequest(
256	                kind: head.kind, cacheDir: head.cacheDir, media: head.media, url: head.url,
257	                stamp: head.stamp, input: head.input,
258	                ranges: AnalysisStore.merged(requests.flatMap(\.ranges)))
259	            return FacesWant(
260	                track: window.track, clip: window.span.clip, media: window.media, request: request)
261	        }
262	    }
263	}
