265	extension AnalysisClipTimes {
266	    /// The forward source tick at `t` ticks from the clip's start: the inverse of
267	    /// `clipTime(ofSource:)` (its source map when it ramps, its speed when not, the reversed
268	    /// mirror last).
269	    func source(atClip t: Ticks) -> Int64 {
270	        let played: Int64
271	        if let map {
272	            played = Int64(map.source(atClip: Double(t)).rounded())
273	        } else {
274	            played = sourceIn + Int64((Double(t) * speed).rounded())
275	        }
276	        return pivot.map { ReverseMirror.mirrored(played, about: $0) } ?? played
277	    }
278	}
