57	extension SpeakerSwitch {
58	    /// "N shots: k on <name>, …. Adds M clips." — the angles in the order they first show,
59	    /// each named by `names` (a track id when it has none).
60	    static func summary(_ shots: [Shot], added: Int, names: [UInt32: String]) -> String {
61	        var order: [UInt32] = []
62	        var counts: [UInt32: Int] = [:]
63	        for shot in shots {
64	            if counts[shot.angle] == nil { order.append(shot.angle) }
65	            counts[shot.angle, default: 0] += 1
66	        }
67	        let each = order.map { "\(counts[$0] ?? 0) on \(names[$0] ?? "track \($0)")" }
68	        let count = shots.count == 1 ? "1 shot" : "\(shots.count) shots"
69	        let adds = added == 1 ? "1 clip" : "\(added) clips"
70	        return "\(count): \(each.joined(separator: ", ")). Adds \(adds)."
71	    }
