78	        for (track, name) in zip(tracks, names) {
79	            if names.filter({ $0 == name }).count > 1 {
80	                out[track] = "\(name) (\((snapshot.trackIndex(of: track) ?? 0) + 1))"
81	            } else {
82	                out[track] = name
83	            }
84	        }
