1	import Foundation
2	
3	/// Mouth activity (road map "creator-jobs" SW8, spec §11 SW-81, SW-82): who
4	/// is talking when one microphone hears everyone, from each angle's cached
5	/// `faces` (CJ-30). The largest face is the angle's person; a sample's opening
6	/// is its mouth's gap over its width; activity is the population standard
7	/// deviation of the openings over `window` centred on a sample; a speech step
8	/// is the top angle's when it is `ratio` × the next and above `floor`, else
9	/// crosstalk. Pure: reads no document, file or clock (SW-25); names no `rc_*`.
10	enum FaceActivity {
11	    /// Seconds, centred (SW-81).
12	    static let window: Double = 0.5
13	    /// The top angle's activity is at least this times the next's.
14	    static let ratio: Double = 1.5
15	    /// The standard deviation of gap/width the top must exceed; PROVISIONAL
16	    /// until SW-S3 measures S-PC2 (SW-88).
17	    static let floor: Double = 0.02
18	    /// Seconds: the faces mode's `min_shot` default, SW-S3's middle band (SW-82).
19	    static let minShot: Double = 3.0
20	    /// The first sentence of the sheet's summary and the tool's `note` in the
21	    /// faces mode (SW-82).
22	    static let hedge = "Faces guess who is talking; check the cuts."
23	
24	    /// The face with the largest width × height; ties go to the first in
25	    /// CJ-31's order. nil for no face.
26	    static func largest(_ faces: [AnalysisFaces.Face]) -> AnalysisFaces.Face? {
27	        var best: AnalysisFaces.Face?
28	        var area = -Double.infinity
29	        for face in faces {
30	            let a = Double(face.width) * Double(face.height)
31	            if best == nil || a > area {
32	                best = face
33	                area = a.isNaN ? -.infinity : a
34	            }
35	        }
36	        return best
37	    }
38	
39	    /// The largest face's `mouthGap / mouthWidth`; nil for no frame (pts −1),
40	    /// no face, a non-finite gap or width, or a width ≤ 0.
41	    static func opening(_ sample: AnalysisFaces.Sample) -> Double? {
42	        guard sample.pts >= 0, let face = largest(sample.faces) else { return nil }
43	        let gap = Double(face.mouthGap), width = Double(face.mouthWidth)
44	        guard gap.isFinite, width.isFinite, width > 0 else { return nil }
45	        return gap / width
46	    }
47	
48	    /// Samples each side of the centre: ⌊window/2 · rate⌋ (2 at 10 a second,
49	    /// 1 at 5).
50	    static func halfWidth(rate: Double) -> Int {
51	        guard rate.isFinite, rate > 0 else { return 0 }
52	        return Int((window / 2 * rate + 1e-9).rounded(.down))
53	    }
54	
55	    /// Per index c, the population standard deviation of the non-nil
56	    /// openings in c − half … c + half (clipped to the series); nil when
57	    /// fewer than two are there.
58	    static func activities(_ openings: [Double?], half: Int) -> [Double?] {
59	        let n = openings.count
60	        var out = [Double?](repeating: nil, count: n)
61	        for c in 0..<n {
62	            var values: [Double] = []
63	            for k in max(0, c - half)...min(n - 1, c + half) {
64	                if let v = openings[k] { values.append(v) }
65	            }
66	            guard values.count >= 2 else { continue }
67	            let mean = values.reduce(0, +) / Double(values.count)
68	            let variance = values.reduce(0) { $0 + ($1 - mean) * ($1 - mean) } / Double(values.count)
69	            out[c] = variance.squareRoot()
70	        }
71	        return out
72	    }
73	
74	    /// A step's label over the contesting angles, front first: no speech or
75	    /// no activity → nobody; else the top angle (ties: the front-most) when
76	    /// top ≥ `ratio` × the next (0 when alone) and top > `floor`, otherwise
77	    /// crosstalk. `person` names the ANGLE track.
78	    static func label(
79	        speech: Bool, activities: [(angle: UInt32, activity: Double?)], ratio: Double,
80	        floor: Double
81	    ) -> SpeakerSwitch.Label {
82	        guard speech else { return .nobody }
83	        var top: (angle: UInt32, value: Double)?
84	        var next = 0.0
85	        for case let (angle, value?) in activities {
86	            if let current = top {
87	                if value > current.value {
88	                    next = current.value
89	                    top = (angle, value)
90	                } else if value > next {
91	                    next = value
92	                }
93	            } else {
94	                top = (angle, value)
95	            }
96	        }
97	        guard let top else { return .nobody }
98	        return top.value >= ratio * next && top.value > floor ? .person(top.angle) : .crosstalk
99	    }
100	}
