190	/// Clip ▸ Switch Angle ▸'s rows (spec §11 SW-15 (a)), rewritten each time the
191	/// menu opens for the main window's editor; `UIMenu.fillDynamic` asks it for
192	/// a named window. One row per `SwitchAngle.angles` of the ONE selected clip —
193	/// the track's title, its index as the tag, the track id as
194	/// `representedObject` — else the single `placeholder()`.
195	final class SwitchAngleMenuFiller: NSObject, NSMenuDelegate {
196	    static let shared = SwitchAngleMenuFiller()
197	
198	    /// "No Covering Angle": `switchAngle(_:)` with no track, which its
199	    /// validator always turns off. It carries the action so the menu's
200	    /// selector is a live leaf before any project opens (the menu's
201	    /// three-way check, `v2_menu.py` H1).
202	    static func placeholder() -> NSMenuItem {
203	        NSMenuItem(
204	            title: "No Covering Angle",
205	            action: #selector(EditorViewController.switchAngle(_:)), keyEquivalent: "")
206	    }
207	
208	    func menuNeedsUpdate(_ menu: NSMenu) {
209	        fill(menu, for: NSApp.mainWindow)
210	    }
211	
212	    func fill(_ menu: NSMenu, for window: NSWindow?) {
213	        let editor = window?.contentViewController as? EditorViewController
214	        var angles: [SwitchAngle.Angle] = []
215	        if let editor, let document = editor.document, editor.selectedClips.count == 1,
216	            let clip = editor.selectedClips.first
217	        {
218	            angles = SwitchAngle.angles(for: clip, in: document.editedProject.snapshot)
219	        }
220	        menu.removeAllItems()
221	        guard !angles.isEmpty else {
222	            menu.addItem(Self.placeholder())
223	            return
224	        }
225	        for (index, angle) in angles.enumerated() {
226	            let item = NSMenuItem(
227	                title: angle.title,
228	                action: #selector(EditorViewController.switchAngle(_:)), keyEquivalent: "")
229	            item.tag = index
230	            item.representedObject = NSNumber(value: angle.track)
231	            menu.addItem(item)
232	        }
233	    }
234	}
