35	    /// The container `set_scope` has open, as `text_behind_subject` reads it:
36	    /// no `scope` key, on the main thread, committed through
37	    /// `performGroupedEdit` (which stamps that scope on the ops).
38	    func switchAngle(_ a: [String: Any]) throws -> String {
39	        let document = try target(a)
40	        let clip = try idArg(a, "clip")
41	        let angle = try idArg(a, "angle")
42	        let container =
43	            effectiveScope(document).flatMap { document.project.scoped($0) } ?? document.project
44	        let answer: SwitchAngle.Answer
45	        do {
46	            answer = try SwitchAngle.plan(clip: clip, angle: angle, in: container)
47	        } catch let error as ToolError {
48	            throw error
49	        } catch {
50	            throw ToolError(message: error.localizedDescription)
51	        }
52	        switch answer {
53	        case .refused(let reason):
54	            throw ToolError(message: reason)
55	        case .plan(let plan):
56	            _ = try performGroupedEdit(document, plan.actionName, plan.ops)
57	            // Written by hand so the keys keep SW-15's order.
58	            let step = try JSONSerialization.data(
59	                withJSONObject: plan.actionName, options: .fragmentsAllowed)
60	            let project = try JSONSerialization.data(withJSONObject: summary(document))
61	            let pieces = plan.pieces.map(String.init).joined(separator: ",")
62	            let text = "{\"ok\":true,\"step\":\(String(decoding: step, as: UTF8.self)),"
63	                + "\"pieces\":[\(pieces)],\"transitions_removed\":\(plan.transitionsRemoved),"
64	                + "\"project\":\(String(decoding: project, as: UTF8.self))}"
65	            return try callResult(content: [["type": "text", "text": text]], isError: false)
66	        }
67	    }
