71	    /// What the first hop resolved: the document, the values, and the project and scope the
72	    /// call read, which the last hop requires unchanged (SW-86).
73	    private struct SpeakerCall {
74	        let document: ProjectDocument
75	        let settings: SpeakerSwitch.Settings
76	        let pairing: SpeakerSwitch.Pairing?
77	        let range: (from: Ticks, to: Ticks)?
78	        let track: UInt32?
79	        let asked: ReelProject
80	        let scope: UInt32?
81	    }
