320	    /// SW-26's numbers and `crosstalk`, each refused outside its range in auto_zoom's form.
321	    private func speakerSettings(_ a: [String: Any]) throws -> SpeakerSwitch.Settings {
322	        typealias S = SpeakerSwitch.Settings
323	        func plain(_ v: Double) -> String {
324	            v.rounded() == v && abs(v) < 1e15 ? String(Int64(v)) : String(v)
325	        }
326	        func number(_ key: String, _ unit: String, _ range: ClosedRange<Double>) throws
327	            -> Double?
328	        {
329	            guard let v = try doubleArg(a, key) else { return nil }
330	            guard v.isFinite, range.contains(v) else {
331	                throw ToolError(
332	                    message: "\(key) is \(plain(v))\(unit); it runs "
333	                        + "\(plain(range.lowerBound))–\(plain(range.upperBound))\(unit).")
334	            }
335	            return v
336	        }
337	        var s = S()
338	        s.minShot = try number("min_shot", " s", S.minShotRange) ?? s.minShot
339	        s.minTurn = try number("min_turn", " s", S.minTurnRange) ?? s.minTurn
340	        s.lead = try number("lead", " s", S.leadRange) ?? s.lead
341	        s.bleedDB = try number("bleed_db", " dB", S.bleedRange) ?? s.bleedDB
342	        s.dominanceDB = try number("dominance_db", " dB", S.dominanceRange) ?? s.dominanceDB
343	        s.wideAfter = try number("wide_after", " s", S.wideAfterRange)
344	        if let crosstalk = try stringArg(a, "crosstalk") {
345	            guard let value = SpeakerSwitch.Crosstalk(rawValue: crosstalk) else {
346	                throw ToolError(
347	                    message: "crosstalk is \"\(crosstalk)\"; it is \"wide\" or \"hold\".")
348	            }
349	            s.crosstalk = value
350	        }
351	        return s
352	    }
353	}
