3	/// Who is active on each step (SW-21) and the shots those turns make (SW-22).
4	/// Pure; `SpeakerSwitch.swift` says what the switch is.
5	extension SpeakerSwitch {
6	    static var stepTicks: Ticks { MediaPeaks.bucketTicks }
7	
8	    /// The nearest-rank percentile `sorted[⌈p·n⌉ − 1]`; nil for no values.
9	    static func percentile(_ values: [Double], _ p: Double) -> Double? {
10	        guard !values.isEmpty else { return nil }
11	        let sorted = values.sorted()
12	        let rank = Int((p * Double(sorted.count) - 1e-9).rounded(.up))
13	        return sorted[min(sorted.count - 1, max(0, rank - 1))]
14	    }
15	
16	    // MARK: - SW-21
17	
18	    /// One label per step. Every microphone's series must be the same length.
19	    static func labels(_ microphones: [Microphone], settings: Settings) -> [Label] {
20	        activeSets(microphones, settings: settings).map { active in
21	            switch active.count {
22	            case 0: return .nobody
23	            case 1: return .person(active[0])
24	            default: return .crosstalk
25	            }
26	        }
27	    }
28	
29	    /// The microphone tracks active on each step (SW-21), a dominant one alone.
30	    static func activeSets(_ microphones: [Microphone], settings: Settings) -> [[UInt32]] {
31	        let count = microphones.map(\.level.count).min() ?? 0
32	        let threshold = settings.voiceThreshold
33	        // P and F per microphone; a microphone with no speech is never active.
34	        let gauges: [(p: Double, f: Double)?] = microphones.map { mic in
35	            var speech: [Double] = []
36	            var quiet: [Double] = []
37	            for k in 0..<count where mic.covered[k] {
38	                if mic.voice[k] >= threshold { speech.append(mic.level[k]) } else {
39	                    quiet.append(mic.level[k])
40	                }
41	            }
42	            guard let p = percentile(speech, 0.9) else { return nil }
43	            return (p, percentile(quiet, 0.1) ?? -.infinity)
44	        }
45	        var out: [[UInt32]] = []
46	        out.reserveCapacity(count)
47	        for k in 0..<count {
48	            var active: [(track: UInt32, over: Double)] = []
49	            for (index, mic) in microphones.enumerated() {
50	                guard let gauge = gauges[index], mic.covered[k], mic.voice[k] >= threshold
51	                else { continue }
52	                let level = mic.level[k]
53	                guard level >= gauge.p - settings.bleedDB,
54	                    level >= gauge.f + settings.floorMarginDB
55	                else { continue }
56	                active.append((mic.track, level - gauge.p))
57	            }
58	            if active.count >= 2, let top = active.max(by: { $0.over < $1.over }),
59	                active.allSatisfy({ $0.track == top.track
60	                    || top.over - $0.over >= settings.dominanceDB })
61	            {
62	                active = [top]
63	            }
64	            out.append(active.map(\.track))
65	        }
66	        return out
67	    }
68	
69	    // MARK: - SW-22
70	
71	    struct Run: Equatable { var label: Label; var start: Int; var end: Int }
72	
73	    /// Maximal runs of equal labels, in step indices.
74	    static func runs(_ labels: [Label]) -> [Run] {
75	        var out: [Run] = []
76	        for (k, label) in labels.enumerated() {
77	            if var last = out.last, last.label == label {
78	                last.end = k + 1
79	                out[out.count - 1] = last
80	            } else {
81	                out.append(Run(label: label, start: k, end: k + 1))
82	            }
83	        }
84	        return out
85	    }
86	
87	    /// SW-22 (a), the crosstalk half: each maximal stretch of non-crosstalk runs lying between two
88	    /// crosstalk runs, shorter than `bridge` in total, becomes crosstalk; the runs it joins merge.
89	    static func bridgingCrosstalk(_ runs: [Run], under bridge: Ticks) -> [Run] {
90	        var out: [Run] = []
91	        var index = 0
92	        while index < runs.count {
93	            let run = runs[index]
94	            if run.label != .crosstalk, var last = out.last, last.label == .crosstalk,
95	                let next = runs[index...].firstIndex(where: { $0.label == .crosstalk }),
96	                Ticks(runs[next].start - run.start) * stepTicks < bridge
97	            {
98	                last.end = runs[next].end
99	                out[out.count - 1] = last
100	                index = next + 1
101	                continue
102	            }
103	            out.append(run)
104	            index += 1
105	        }
106	        return out
107	    }
108	
109	    static func shots(
110	        labels: [Label], from: Ticks, to: Ticks, fps: Fps, pairing: Pairing,
111	        angles: [AngleTrack], settings: Settings
112	    ) -> [Shot] {
113	        let step = stepTicks
114	        func ticks(_ seconds: Double) -> Ticks { Ticks((seconds * Double(ReelTime.perSecond)).rounded()) }
115	        func snap(_ t: Ticks) -> Ticks { ReelTime.snapToFrame(t, fps: fps) }
116	        guard to > from, let front = angles.first?.track else { return [] }
117	        let wide = pairing.wide.flatMap { w in angles.contains { $0.track == w } ? w : nil }
118	
119	        // (a), (b): the turns.
120	        let turns = bridgedRuns(labels, settings: settings)
121	
122	        // (c), (d), (e): the starts.
123	        var starts: [(angle: UInt32, start: Ticks)] = []
124	        if let wide { starts.append((wide, from)) }
125	        for turn in turns {
126	            let length = Ticks(turn.end - turn.start) * step
127	            let angle: UInt32?
128	            switch turn.label {
129	            case .nobody: angle = nil
130	            case .person(let mic):
131	                angle = length >= ticks(settings.minTurn)
132	                    ? pairing.speakers.first(where: { $0.mic == mic })?.angle : nil
133	            case .crosstalk:
134	                angle = length >= ticks(settings.crosstalkMin) && settings.crosstalk == .wide
135	                    ? wide : nil
136	            }
137	            guard let angle, angle != starts.last?.angle else { continue }
138	            let at = max(
139	                starts.last?.start ?? from, from,
140	                snap(from + Ticks(turn.start) * step - ticks(settings.lead)))
141	            if starts.last?.start == at {
142	                starts.removeLast()
143	                if starts.last?.angle == angle { continue }
144	            }
145	            starts.append((angle, at))
146	        }
147	        if starts.isEmpty { starts.append((front, from)) }
148	        starts[0].start = from
149	        var tiled = tile(starts, to: to)
150	
151	        // (f) the wide after a person has held the screen `wide_after`.
152	        if let wide, let after = settings.wideAfter, after > 0 {
153	            var out: [Shot] = []
154	            for shot in tiled {
155	                guard shot.angle != wide else {
156	                    out.append(shot)
157	                    continue
158	                }
159	                var held = shot.start
160	                while true {
161	                    let cut = snap(held + ticks(after))
162	                    guard cut > held, cut < shot.end else { break }
163	                    let back = min(shot.end, snap(cut + ticks(settings.minShot)))
164	                    out.append(Shot(angle: shot.angle, start: held, end: cut))
165	                    out.append(Shot(angle: wide, start: cut, end: back))
166	                    held = back
167	                    if back >= shot.end { break }
168	                }
169	                if held < shot.end { out.append(Shot(angle: shot.angle, start: held, end: shot.end)) }
170	            }
171	            tiled = out
172	        }
173	
174	        // (g) every uncovered piece handed on; (h) the merges.
175	        let covered = handOff(tiled, angles: angles, wide: wide)
176	        return merged(covered, angles: angles, minShot: ticks(settings.minShot))
177	    }
