21	    @objc func switchAngle(_ sender: Any?) {
22	        guard let document, view.window?.attachedSheet == nil,
23	            let track = ((sender as? NSMenuItem)?.representedObject as? NSNumber)?.uint32Value,
24	            let clip = switchAngleClip
25	        else {
26	            NSSound.beep()
27	            return
28	        }
29	        let answer: SwitchAngle.Answer
30	        do {
31	            answer = try SwitchAngle.plan(
32	                clip: clip.id, angle: track, in: document.editedProject)
33	        } catch {
34	            NSSound.beep()
35	            return
36	        }
37	        switch answer {
38	        case .plan(let plan):
