83	    /// SW-26 (c) as SW-86 amends it: on the server thread (`creatorOffMainTools`), the container
84	    /// `set_scope` has open, no `scope` key. One main hop reads the arguments, `read` and the faces
85	    /// the store still misses; with none it plans and edits in that hop. Otherwise the call wants
86	    /// them under an owner of its own and waits at most `AnalysisLane.callWaitLimit`, then a last
87	    /// hop refuses a changed project or scope, reads again and runs SW2b's sequence: Replace's
88	    /// track, `plan` and `edit`, `apply: false` answering without editing, one
89	    /// `performGroupedEdit`.
90	    func switchBySpeaker(_ a: [String: Any]) throws -> String {
91	        let stop = AgentLane.shared.callCancel  // the assistant's Stop (spec §11 AI-16)
92	        guard !Thread.isMainThread else {
93	            throw ToolError(
94	                message: "switch_by_speaker must run on the server thread — its name is missing "
95	                    + "from AgentServer.creatorOffMainTools.")
96	        }
97	        let (call, wants, answer): (SpeakerCall, [SpeakerSwitch.FacesWant], String?) = try onMain {
98	            let call = try speakerCall(a)
99	            let input = try speakerInput(call)
100	            let wants: [SpeakerSwitch.FacesWant]
101	            do {
102	                wants = try SpeakerSwitch.facesWanted(input, in: call.document)
103	            } catch {
104	                throw ToolError(message: error.localizedDescription)
105	            }
106	            guard wants.isEmpty else { return (call, wants, nil) }
107	            return (call, wants, try finishSpeakerSwitch(a, call, input))
108	        }
109	        if let answer { return answer }
110	        try waitForFaces(wants, document: call.document, stop: stop)
111	        return try onMain {
112	            guard call.document.project === call.asked, call.document.scope == call.scope else {
113	                throw ToolError(
114	                    message: "the project changed while \(SpeakerSwitch.actionName) was "
115	                        + "analyzing, so nothing was switched. Call switch_by_speaker again.")
116	            }
