219	    /// SW2b's sequence over `input`, main thread: Replace's track, `plan`, `edit`, then the edit
220	    /// unless `apply` is false, and the answer with SW-86's `mode` and, in the faces mode, `note`.
221	    private func finishSpeakerSwitch(
222	        _ a: [String: Any], _ call: SpeakerCall, _ input: SpeakerSwitch.Input
223	    ) throws -> String {
224	        let document = call.document
225	        let track = call.track
226	        let snapshot = document.editedProject.snapshot
227	        let refused = "Switch by Speaker was refused: "
228	        if let track,
229	            let why = SpeakerSwitch.replaceRefusal(
230	                track, input: input, selection: document.selection, in: snapshot)
231	        {
232	            throw ToolError(message: refused + why)
233	        }
234	        guard case .planned(let shots, let added) = SpeakerSwitch.plan(input) else {
235	            if case .refused(let reasons) = SpeakerSwitch.plan(input) {
236	                throw ToolError(message: refused + reasons.joined(separator: " "))
237	            }
238	            throw ToolError(message: refused + "nothing was planned.")
239	        }
240	        let mute = try boolArg(a, "mute_cameras") ?? SpeakerSwitch.muteDefault(input)
241	        let answer: SpeakerSwitch.EditAnswer
242	        do {
243	            answer = try SpeakerSwitch.edit(
244	                shots, input: input, muteCameras: mute, replacing: track,
245	                selection: document.selection, in: document.editedProject)
246	        } catch {
247	            throw ToolError(message: error.localizedDescription)
248	        }
249	        let edit: SpeakerSwitch.Edit
250	        switch answer {
251	        case .refused(let why):
252	            // (a)'s refusal already says where; (h)'s is the bare sentence.
253	            throw ToolError(
254	                message: why.hasPrefix("Switch by Speaker was refused") ? why : refused + why)
255	        case .edit(let made):
256	            edit = made
257	        }
258	
259	        let apply = try boolArg(a, "apply") ?? true
260	        if apply {
261	            try performGroupedEdit(document, SpeakerSwitch.actionName, edit.ops)
262	            document.selection = edit.selection
263	        }
264	        func id(_ value: UInt32?) -> Any { value.map { NSNumber(value: $0) } ?? NSNull() }
265	        var fields: [String: Any] = [
266	            "ok": true,
267	            "applied": apply,
268	            "track": apply || track != nil ? id(edit.track) : NSNull(),
269	            "shots": shots.map { ["angle": $0.angle, "start": $0.start, "end": $0.end] },
270	            "ops": edit.ops.count,
271	            "added": added,
272	            "speakers": input.pairing.speakers.map { ["mic": id($0.mic), "angle": id($0.angle)] },
273	            "wide": id(input.pairing.wide),
274	            "mute_cameras": mute,
275	            "project": summary(document),
276	        ]
277	        if apply { fields["step"] = SpeakerSwitch.actionName }
278	        let mode = SpeakerSwitch.mode(input.pairing)
279	        fields["mode"] = mode.rawValue
280	        if mode == .faces { fields["note"] = FaceActivity.hedge }
281	        return try jsonResult(fields)
282	    }
