284	    /// Wants every request under an owner of the call's own and waits (`waitForShots`' shape);
285	    /// throws naming the first media not landed when one failed, the call was stopped, or the
286	    /// bound passed (SW-86).
287	    private func waitForFaces(
288	        _ wants: [SpeakerSwitch.FacesWant], document: ProjectDocument, stop: AgentCallCancel?
289	    ) throws {
290	        let lane = AnalysisLane.shared
291	        let requests = wants.map(\.request)
292	        let owner = lane.newOwner()
293	        defer { lane.release(owner: owner) }
294	        lane.want(
295	            requests, owner: owner,
296	            alive: { document.isOpenForAnalysis && !(stop?.isCancelled ?? false) },
297	            settled: { document.packageContentsDidChangeOnDisk() })
298	        let outcome = lane.wait(
299	            for: requests, owner: owner,
300	            deadline: Date().addingTimeInterval(AnalysisLane.callWaitLimit),
301	            cancelled: { stop?.isCancelled ?? false })
302	        let open = wants.first { lane.run(of: $0.request)?.outcome != .landed } ?? wants[0]
303	        let media = open.media.id
304	        switch outcome {
305	        case .landed: return
306	        case .failed(let why):
307	            throw ToolError(message: "The faces analysis of media \(media) failed: \(why).")
308	        case .cancelled:
309	            throw ToolError(
310	                message: "The faces analysis of media \(media) was stopped before it finished, "
311	                    + "so nothing was switched.")
312	        case .timedOut:
313	            throw ToolError(
314	                message: "The faces analysis of media \(media) did not finish in the "
315	                    + "\(Int(AnalysisLane.callWaitLimit)) s a call waits; what it covered is "
316	                    + "kept — call switch_by_speaker again to continue.")
317	        }
318	    }
